[{"order":1,"type":"heading","text":"Graceful Shutdown and Connection Draining in Express.js"},{"order":2,"type":"paragraph","text":"When deploying modern web applications, ensuring zero-downtime deployments and preventing data corruption during restarts is critical. In Node.js and Express.js, this is achieved through graceful shutdown and connection draining."},{"order":3,"type":"subheading","text":"Understanding the Problem"},{"order":4,"type":"paragraph","text":"By default, when an Express application receives a termination signal like SIGTERM, it immediately closes the server. Any active HTTP requests in flight are abruptly terminated, resulting in connection reset errors for clients and potential data corruption if database transactions are left half-completed."},{"order":5,"type":"subheading","text":"The Solution: Graceful Shutdown"},{"order":6,"type":"paragraph","text":"A graceful shutdown involves three main steps:"},{"order":7,"type":"bullet_point","text":"Stop accepting new incoming connections."},{"order":8,"type":"bullet_point","text":"Wait for existing requests to finish processing (connection draining)."},{"order":9,"type":"bullet_point","text":"Close database connections, message queues, and other external resources before exiting the process."},{"order":10,"type":"subheading","text":"Implementation Example"},{"order":11,"type":"paragraph","text":"Below is a complete implementation of an Express server that handles SIGTERM signals cleanly."},{"order":12,"type":"code","text":"const express = require('express');
const app = express();

app.get('/', (req, res) => {
  setTimeout(() => {
    res.send('Hello from Express!');
  }, 3000);
});

const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

const shutdown = () => {
  console.log('Received kill signal, shutting down gracefully.');

  server.close(() => {
    console.log('Closed out remaining connections.');

    // Close database connections here
    // mongoose.connection.close(false, () => { process.exit(0); });

    process.exit(0);
  });

  // Force shutdown if connections do not drain within 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);"},{"order":13,"type":"subheading","text":"Best Practices"},{"order":14,"type":"bullet_point","text":"Always implement a timeout fallback using setTimeout so that hanging requests cannot block your deployment pipeline indefinitely."},{"order":15,"type":"bullet_point","text":"Coordinate your load balancer health checks to mark the instance as unhealthy before sending the shutdown signal."}]
